/*
 * counter.c: a tiny event counter. Do not edit this file; clings compiles
 * it together with multifile2.c.
 */

#include "counter.h"

// A global variable with external linkage: other .c files may use it, but
// only after declaring it with `extern int call_count;`.
int call_count = 0;

// `static` at file scope means internal linkage: `helper` is private to
// this file, and the linker never shows it to any other .c file.
static int helper(void) {
    return 1;
}

void count_event(void) {
    call_count += helper();
}

int get_count(void) {
    return call_count;
}
